function UIActionPointMapDialog:InitData()
    self._allQuestIds = {}
    self._regionVo = ActionUtils.GetRegionSecondaryMapVo(self._regionId)
    if not self._regionVo then
        return
    end
    self._mapId = checkNumber(self._regionVo.regionBelong)

    local lastId = checkNumber(KCookie.Get("LastEntryBattleQuestId"))

    KCookie.Set("LastEntryBattleQuestId", 0)
    if lastId > 0 then
        self._curSelectQuestId = lastId
    end
    --歼灭战
    if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Annihilation then
        self._annihilationId = ActionUtils.GetCurAnnihilationId(self._mapId)
        local vo = ActionUtils.GetRegionAnnihilationTypeVo(self._annihilationId)
        local t = checkTable(CfUtils.Split(vo.contentLevel))
        for k, v in pairs(t) do
            if checkNumber(v) > 0 then
                table.insert(self._allQuestIds, checkNumber(v))
                --if checkNumber(self._curSelectQuestId) == 0 then
                --    self._curSelectQuestId = checkNumber(v)
                --end
            end
        end
    elseif checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Sp then
        local vo = ActionUtils.GetRegionDailyTypeVo(self._dailyType)
        local t = checkTable(CfUtils.Split(vo.content))
        for k, v in pairs(t) do
            if checkNumber(v) > 0 then
                table.insert(self._allQuestIds, checkNumber(v))
                --if checkNumber(self._curSelectQuestId) == 0 then
                --    self._curSelectQuestId = checkNumber(v)
                --end
            end
        end
    elseif checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle then
        local t = checkTable(CfUtils.Split(self._regionVo.content))
        local _t = {}
        self._isEquip = false
        for k, v in pairs(t) do
            if checkNumber(v) > 0 then
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(v)
                if vo then
                    --食材
                    local levelType = checkNumber(vo.levelType)
                    if levelType == Constants.RegionSecondQuestType.Food then
                        if not _t[checkString(vo.foodType)] then
                            _t[checkString(vo.foodType)] = {}
                        end
                        table.insert(_t[checkString(vo.foodType)], v)
                    elseif levelType == Constants.RegionSecondQuestType.Equip then
                        self._isEquip = true
                    end
                    --if checkNumber(self._curSelectQuestId) == 0 then
                    --    self._curSelectQuestId = checkNumber(v)
                    --end
                end
            end
        end

        --食材本
        if not self._isEquip then
            local allIds = {}
            local _title = {}

            for k, ids in pairs(_t) do
                for _, v in pairs(ids) do
                    table.insert(allIds, checkNumber(v))
                end
            end
            table.sort(allIds, function(a, b)
                return checkNumber(a) < checkNumber(b)
            end)

            for k, v in pairs(allIds) do
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(v)
                if not _title[checkString(vo.foodType)] then
                    _title[checkString(vo.foodType)] = 1

                    table.insert(self._allQuestIds, -checkNumber(vo.foodType))
                end
                table.insert(self._allQuestIds, v)
            end
        else
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(self._allQuestIds, checkNumber(v))
                end
            end
        end
    else
        local t = checkTable(CfUtils.Split(self._regionVo.content))
        for k, v in pairs(t) do
            if checkNumber(v) > 0 then
                table.insert(self._allQuestIds, checkNumber(v))
                --if checkNumber(self._curSelectQuestId) == 0 then
                --    self._curSelectQuestId = checkNumber(v)
                --end
            end
        end
    end
    --缓冲下来的不是当前需要的关卡
    local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
    if not ind then
        if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle then
            ---目前是食材本
            self._curSelectQuestId = checkNumber(self._allQuestIds[2])
        else
            ---其他类型的逻辑
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            ----历史最后战力
            local overseaMaxTeamCombatVal = checkNumber(playerComponent.playerDojo.overseaMaxTeamCombatVal)
            self._curSelectQuestId = checkNumber(self._allQuestIds[1])
            ----战力的逻辑处理
            ---@type QuestConfMgr
            local questConfMgr = QuestConfMgr:GetInstance()
            local posPassed = 0
            local posCombat = 0
            for index, questId in pairs(self._allQuestIds) do
                questId = checkNumber(questId)
                local isUnlock = questConfMgr:IsUnlockQuest(questId)
                local isPassed = questConfMgr:IsPassQuest(questId)
                if isUnlock then
                    ---解锁的关卡
                    ---@type QuestDailyVo
                    local vo = questConfMgr:GetQuestVoById(questId)
                    if vo and vo.proposalLevel and overseaMaxTeamCombatVal >= checkNumber(vo.proposalLevel) then
                        posCombat = index
                    end
                    if isPassed then
                        posPassed = index
                    end
                end
            end
            local position = math.max(math.max(posPassed, posCombat), 1)
            self._curSelectQuestId = checkNumber(self._allQuestIds[position])
        end
    end
end

function UIActionPointMapDialog:FillSelf()
    print('-->>>', self._regionVo.type, self._isEquip)
    if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle
            or checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Sp then
        CfUtils.SetActive(self.NormalPanel, true)
        if self._isEquip then
            self:FillCommonBattleInfo()
            self:FillQuestInfo()
            self:FillEquipQuestInfo()
        else
            self:FillCommonBattleInfo()
            self:FillQuestInfo()
            self:FillSpInfo()
        end
    elseif checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Boss or
            checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.ExpBattle or
            checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.ParticleBattle
    then
        CfUtils.SetActive(self.NormalPanel, true)
        self:FillCommonBattleInfo()
        self:FillBossInfo()
        self:FillQuestInfo()

    elseif checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Annihilation then
        CfUtils.SetActive(self.NormalPanel, false)
        CfUtils.SetActive(self.BossPanel, true)
        self:FillAnnihilationInfo()
        self:FillAnnihilationQuestInfo()

        self:StartTimeDown()
    end
end

--装备本
function UIActionPointMapDialog:FillEquipQuestInfo()
    if not self._isEquip then
        return
    end
    --@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
    local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
    CfUtils.SetActive(self.equipActivityTrans, status == 1)
    if status == 1 and times > 0  then
        CfUtils.SetActive(self.equipActivityTrans:Find("TextDesc"), false)
        CfUtils.FillText(self.equipActivityTrans:Find("TextDesc"),   localize('全副武装副本持续中'))
        CfUtils.FillText(self.equipActivityTrans:Find("TextRemind"),  localize('装备副本情绪消耗降低！'))
    end
    CfUtils.SetActive(self.EquipGroup, true)
    CfUtils.FillImage(self.ImgCollection, self._regionVo.showBG)
    CfUtils.FillImage(self.ImgMaterial, self._regionVo.showIcon1)
    CfUtils.FillImage(self.ImgEquip, self._regionVo.showIcon2)
    CfUtils.FillText(self.TxtState, self._regionVo.desc)
    if checkNumber(self._regionVo.mainEquipType) > 0 then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", self._regionVo.mainEquipType)
        if vo then
            CfUtils.FillImage(self.ImgType2, vo.icon)
        end
    end
end

