--歼灭战有倒计时信息
function UIActionPointMapDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local data = ActionUtils.GetAnnihilationInfo(self._mapId)
        CfUtils.FillText(self.TxtNumber2, CfUtils.GetTimeHMS(data.remainTime))
    end, CountDownTime, false, true)
end

--歼灭战信息
function UIActionPointMapDialog:FillAnnihilationInfo()
    CfUtils.SetActive(self.BgGroup, true)
    local go = self.BossRoleGroup.transform:Find("Boss" .. self._annihilationId)
    CfUtils.SetActive(go, true)

    local vo = ActionUtils.GetRegionAnnihilationTypeVo(self._annihilationId)
    if not vo then
        return
    end
    CfUtils.FillImage(self.ImgBgBoss, vo.bgPath)

    local data = ActionUtils.GetAnnihilationInfo(self._mapId)

    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.FillText(self.TxtNumber2, CfUtils.GetTimeHMS(data.remainTime))

    if self._isInitAnnihilationList then
        GameUtils.ReloadData(self.CellGroup, table.count(self._allQuestIds))
    else
        self.CellGroup:InitListView(table.count(self._allQuestIds), Bind(self, self.OnRefreshAnnihilationIndex))
        self._isInitAnnihilationList = true
    end

    SetButtonAction(self.BossPanel.transform:Find("LeftPanel/InfoGroup"), function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIBossDetailDialog, parameters = { levelId = self._curSelectQuestId } })
    end)
end

function UIActionPointMapDialog:OnRefreshAnnihilationIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local id = self._allQuestIds[index + 1]

    local go = cell.gameObject
    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapBossNode")
    if scr then
        scr:Refresh(id, self._mapId, index + 1)
        scr:FillSelect(checkNumber(id) == checkNumber(self._curSelectQuestId))
    end
    SetButtonAction(go, Bind(self, self.OnSelectAnnihilationQuest, id))

    return cell
end

function UIActionPointMapDialog:OnSelectAnnihilationQuest(questId)
    if self._curSelectQuestId > 0 then
        local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
        if checkNumber(ind) > 0 then
            local go = self.CellGroup:GetShownItemByItemIndex(ind - 1)
            if go then
                local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapBossNode")
                if scr then
                    scr:FillSelect(false)
                end
            end
        end
    end

    self._curSelectQuestId = checkNumber(questId)
    local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
    if checkNumber(ind) > 0 then
        local go = self.CellGroup:GetShownItemByItemIndex(ind - 1)
        if go then
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapBossNode")
            if scr then
                scr:FillSelect(true)
            end
        end
    end

    self:FillAnnihilationQuestInfo()
end

