--普通战斗和boss
function UIActionPointMapDialog:FillCommonBattleInfo()
    if self._isInitLoopList then
        GameUtils.ReloadData(self.ListView, table.count(self._allQuestIds))
    else
        self.ListView:InitListView(table.count(self._allQuestIds), Bind(self, self.OnRefreshIndex))
        self._isInitLoopList = true
    end
end

function UIActionPointMapDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell
    local id

    if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle then
        id = self._allQuestIds[index + 1]
        if checkNumber(id) < 0 then
            cell = listView:NewListViewItem("CellTitle")
            local go = cell.gameObject
            CfUtils.SetUISwitchImage(go.transform:Find("ImgIcon"), (-checkNumber(id)))
            CfUtils.SetUISwitchText(go.transform:Find("TxtTitle"), (-checkNumber(id)))
        else
            cell = listView:NewListViewItem("CellNormal")
            local go = cell.gameObject
            ----@type UIActionPointMapNode
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapNode")

            if scr then
                scr:RefreshCommonBattle(id, index + 1)
                scr:FillSelect(checkNumber(id) == checkNumber(self._curSelectQuestId))
            end
            SetButtonAction(go, Bind(self, self.OnSelectQuest, id))
        end
    else
        cell = listView:NewListViewItem("Cell")
        id = self._allQuestIds[index + 1]

        local go = cell.gameObject
        ---@type UIActionPointMapNode
        local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapNode")
        if scr then
            scr:Refresh(id, index + 1)
            scr:FillSelect(checkNumber(id) == checkNumber(self._curSelectQuestId))
        end

        SetButtonAction(go, Bind(self, self.OnSelectQuest, id))
    end

    return cell
end

function UIActionPointMapDialog:OnSelectQuest(questId)
    if self._curSelectQuestId > 0 then
        local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
        if checkNumber(ind) > 0 then
            local go = self.ListView:GetShownItemByItemIndex(ind - 1)
            if go then
                local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapNode")
                if scr then
                    scr:FillSelect(false)
                end
                --CfUtils.PlayAnimation(go.gameObject, "ActionPointMapDialog_Normal_Cell_Locked")
            end
        end
    end

    self._curSelectQuestId = checkNumber(questId)
    local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
    if checkNumber(ind) > 0 then
        local go = self.ListView:GetShownItemByItemIndex(ind - 1)
        if go then
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionPointMapDialog.UIActionPointMapNode")
            if scr then
                scr:FillSelect(true)
            end
            --CfUtils.PlayAnimation(go.gameObject, "ActionPointMapDialog_Normal_Cell_Selecting")
        end
    end

    self:FillQuestInfo()
end

--展示关卡信息
function UIActionPointMapDialog:FillQuestInfo()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectQuestId)
    if not vo then
        return
    end
    CfUtils.FillText(self.TxtType, vo.engName)
    CfUtils.SetUISwitchImage(self.ImgType, vo.levelType)
    CfUtils.FillText(self.TxtTitle, vo.name)
    CfUtils.FillText(self.TxtType2, ActionUtils.GetQuestTypeName(vo.levelType))
    CfUtils.FillText(self.TxtDesc, vo.describe)
    if checkNumber(vo.levelType) == Constants.RegionSecondQuestType.Equip then
        ---装备本
        --@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
        local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
        CfUtils.SetActive(self.equipActivityTrans, status == 1)
        if status == 1  then
            --CfUtils.FillText(self.equipActivityTrans:Find("TextDesc"),   localize('活动今日剩余次数: _num_', {_num_ = times}))
            CfUtils.FillText(self.equipActivityTrans:Find("TextDesc"),   localize('全副武装副本持续中'))
            CfUtils.FillText(self.equipActivityTrans:Find("TextRemind"),  localize('装备副本情绪消耗降低！'))
        end
    end
    local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curSelectQuestId)
    if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Annihilation then
        self._allRewards = checkTable(t)
        if self._isInitRewardLoopList then
            GameUtils.ReloadData(self.ScrollView, table.count(self._allRewards))
        else
            self.ScrollView:InitListView(table.count(self._allRewards), Bind(self, self.OnRefreshRewardIndex))
            self._isInitRewardLoopList = true
        end
    else
        self:FillBoxRewards(t)
    end

    self:FillConsume(self.CommonBtnConsumePop)

    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockQuest(vo.id)
    CfUtils.SetActive(self.CommonBtnConsumePop, true)
    local go = self.NormalPanel.transform:Find("RightPanel/TxtLock")
    CfUtils.SetActive(go, not isUnlock)
    if isUnlock then
        self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B5", localize("进入"))
    else
        self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B4")
        if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle then
            CfUtils.FillText(go, err)
        else
            CfUtils.FillText(go, localize("前置关卡通关解锁"))
        end
    end

    local vo = RewardConfMgr:GetInstance():GetQuestRewardVo(self._curSelectQuestId)
    if vo then
        CfUtils.FillImage(self.NormalPanel.transform:Find("RightPanel/Layout/DungeonInfo/DropGroup/MonetaryRewards/TxtMonetary1/ImgIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(vo.currencyID))
        CfUtils.FillText(self.NormalPanel.transform:Find("RightPanel/Layout/DungeonInfo/DropGroup/MonetaryRewards/TxtMonetary1"), vo.currencyNum)
    end

    self:FillSweepBtnGroup()
end

function UIActionPointMapDialog:FillBoxRewards(rewards)
    local _t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curSelectQuestId)
    local t = {}

    local __t = {}
    for k, v in pairs(_t) do
        if not t[checkString(v.type)] then
            t[checkString(v.type)] = {
                sortKey = checkNumber(v.type),
                data = {}
            }
            table.insert(__t, checkString(v.type))
        end

        table.insert(t[checkString(v.type)].data, v)
    end
    --local rewards = {}
    --for k, v in pairs(t) do
    --    table.insert(rewards, v)
    --end
    --table.sort(rewards, function(a, b)
    --    return checkNumber(a.sortKey) < checkNumber(b.sortKey)
    --end)

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectQuestId)
    if isPass then
        local data = __t[1]
        table.remove(__t, 1)
        table.insert(__t, data)
    end

    for k, v in pairs(__t) do
        local data = t[checkString(v)]
        self:FillBoxReard(data.data, data.sortKey, k)
    end
end

function UIActionPointMapDialog:FillBoxReard(t, type, ind)
    local initParGo = self.Content
    local initGo = self.GoodGroup

    if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Annihilation then
        initParGo = self.ScrollView2.transform:Find("Viewport/Content")
        initGo = initParGo.transform:Find("GoodGroup")
    end

    local go = initParGo.transform:Find("go" .. ind)
    if not go then
        go = CfUtils.InstantiateGo(initGo, initParGo)
        go.name = "go" .. ind
    end

    if table.count(t) <= 0 then
        CfUtils.SetActive(go, false)
        return
    end
    CfUtils.SetUISwitchImage(go.transform:Find("ImgLine"), ind)
    CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), ind)

    local isNotShowBox = (type == Constants.QuestRewardType.FristRewards or type == Constants.QuestRewardType.Captain)
    isNotShowBox = true
    CfUtils.SetActive(go.transform:Find("TitleGroup/TxtFirst"), isNotShowBox)
    CfUtils.SetActive(go.transform:Find("TitleGroup/ImgChest"), not isNotShowBox)

    local name = RewardConfMgr:GetInstance():GetTeamShowRewardTagName(type)
    --if type == Constants.QuestRewardType.RegularReward then
    --    name = localize("必定掉落")
    --elseif type == Constants.QuestRewardType.RareReward then
    --    name = localize("概率掉落")
    --elseif type == Constants.QuestRewardType.FristRewards then
    --    name = localize("首通奖励")
    --elseif type == Constants.QuestRewardType.Raid then
    --    name = localize("扫荡奖励")
    --elseif type == Constants.QuestRewardType.Captain then
    --    name = localize("队长奖励")
    --end

    if not isNotShowBox then
        CfUtils.SetUISwitchImage(go.transform:Find("TitleGroup/ImgChest"), ind - 1)
    else
        local status = (type == Constants.QuestRewardType.FristRewards and 1 or 2)
        --CfUtils.SetUISwitchText(go.transform:Find("TitleGroup/TxtFirst"), status)
    end

    CfUtils.FillText(go.transform:Find("TitleGroup/TxtFirst"), name)

    CfUtils.SetActive(go, true)
    local parGo = go
    local nodeGo = go.transform:Find("GoodPar")
    for k, v in pairs(t) do
        local goodsGo = parGo.transform:Find("go" .. k)
        if not goodsGo then
            goodsGo = CfUtils.InstantiateGo(nodeGo, parGo)
            goodsGo.name = "go" .. k
        end
        CfUtils.SetActive(go, true)

        local num
        if checkNumber(v.num) > 0 then
            num = "x" .. v.num
        end
        CfUtils.SetActive(goodsGo, true)
        CfUtils.RefeshGoodGo2(goodsGo.transform:Find("GoodNode"), v.id, num, nil, nil, function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.id)
            GameUtils.ShowCommonTipsBoard(goodsGo.transform:Find("GoodNode"), goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id, nil, nil)
        end)

        local scr = CfUtils.GetLuaScr(goodsGo.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
        if type == 3 then
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectQuestId)
            if scr then
                scr:SetSanXingGainShow(isPass)
            else
                scr:SetSanXingGainShow(false)
            end
        else
            if scr then
                scr:SetSanXingGainShow(false)
                --scr:SetBonusText(string.format('%g%%', checkNumber(v.probability) / 100), 1)
            end
        end
    end

    if parGo.transform.childCount > table.count(t) then
        for k = table.count(t) + 1, parGo.transform.childCount do
            local goodsGo = parGo.transform:Find("go" .. k)
            CfUtils.SetActive(goodsGo, false)
        end
    end
end

