function UIActionPointMapDialog:OnRefreshRewardIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self._allRewards[index + 1]

    local go = cell.gameObject
    local num
    if checkNumber(data.num) > 0 then
        num = data.num
    end
    CfUtils.RefeshGoodGo2(go.transform:Find("GoodNode"), data.id, nil, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.id)
        GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    return cell
end

