    CfUtils.ShowModuleToast(ActionUtils.GetRuleId())
end

function UIActionPointMapDialog:OnBtnEntry()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockQuest(self._curSelectQuestId, self._mapId)
    if not isUnlock then
        if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.CommonBattle or
                checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Boss or
                checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.ExpBattle or
                checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.ParticleBattle or
                checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Annihilation then
            GameUtils.Toast(err)
        elseif checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Sp then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectQuestId)
            local str1 = localize("通关前置关卡")
            local str2 = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level), 0)
            local str3 = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, checkString(vo.unlockRegion), 0)

            local str = str1 .. str2
            if checkNumber(vo.unlockRegion) > 0 then
                str = str .. "," .. str3
            end
            GameUtils.Toast(str1)
        end
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curSelectQuestId } }, {
        { id = Constants.UITypeIds.UIActionPointMapDialog },
    })
end

function UIActionPointMapDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        -- UIModule.RemoveDialogRecord(Constants.UITypeIds.UIActionDungoenCollectionDialog)

        self._isFind = false --从二级地图进来的不删地图go
        local uiPages = UIModule.Instance.uiPages
        local uiPageCount = uiPages.Count
        for i = uiPageCount - 1, 0, -1 do
            ---@type Engine.UI.UIPage
            local uiPage = uiPages[i]
            local uiArguments = uiPage.uiArguments
            for argumentsIndex = uiArguments.Count - 1, 0, -1 do
                ---@type Engine.UI.UIArgument
                local argument = uiArguments[argumentsIndex]

                if checkNumber(argument.id) == Constants.UITypeIds.UIActionSecondMapDialog then
                    self._isFind = true
                    break
                end
            end
            if self._isFind then
                break
            end
        end

        CfUtils.SetTopCommonCb()
        SetButtonAction(self.BtnDesc, Bind(self, self.OnBtnDesc))
        SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnEntry))
        SetButtonAction(self.BtnDesc3, Bind(self, self.OnBtnDesc))
        SetButtonAction(self.BtnDesc2, Bind(self, self.OnBtnDesc2))

        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._regionId = checkNumber(argument.id)
        self._dailyType = checkNumber(argument.dailyType)
        self._isFromEntry = checkBool(argument.isFromEntry)
        self._curSelectQuestId = checkNumber(argument.targetQuestId)
        self._regionVo = ActionUtils.GetRegionSecondaryMapVo(self._regionId)

        if not self._regionVo then
            return
        end
        local regionTypeVo = ActionUtils.GetRegionSecondaryTypeVo(self._regionVo.type)
        local regionType = checkNumber(self._regionVo.type)
        if regionType == Constants.RegionSecondMapPointType.Boss
                or regionType == Constants.RegionSecondMapPointType.ExpBattle
                or regionType == Constants.RegionSecondMapPointType.ParticleBattle
        then
            print('--->>', regionTypeVo.name)
            CfUtils.FillText(self.Text, regionTypeVo.name)
            local leftPanel = self.NormalPanel.transform:Find("LeftPanel")
            if leftPanel then
                local imageBossPointImage = leftPanel:Find("BossGroup/BG/ImgBossPoint")
                local bossPointFx = leftPanel:Find("BossGroup/BG/UIFX_ImgBossPoint")
                if imageBossPointImage then
                    if regionType == Constants.RegionSecondMapPointType.Boss then
                        CfUtils.SetUISwitchImage(imageBossPointImage, 1)
                        CfUtils.SetUISwitchImage(bossPointFx, 1)
                    elseif regionType == Constants.RegionSecondMapPointType.ExpBattle then
                        CfUtils.SetUISwitchImage(imageBossPointImage, 3)
                        CfUtils.SetUISwitchImage(bossPointFx, 3)
                    elseif regionType == Constants.RegionSecondMapPointType.ParticleBattle then
                        CfUtils.SetUISwitchImage(imageBossPointImage, 2)
                        CfUtils.SetUISwitchImage(bossPointFx, 2)
                    end
                end
            end
        end
        self._mapId = checkNumber(self._regionVo.regionBelong)

        self._mapGo = RegionQuestMgr:GetInstance():GetCurMapGo(self._mapId)
        self._mapCam = self._mapGo.transform:Find("AreaMap_01_01_Camera").gameObject:GetComponent(typeof(Camera))
        CfUtils.SetActive(self._mapCam, true)
        if checkNumber(KCookie.Get("UIActionSecondMapDialogEntry")) == 0 then
            CfUtils.SetActive(self._mapCam, true)
            local targetGo = self._mapGo.transform:Find("CameraEndPos_" .. self._regionId)
            if targetGo then
                self._mapCam.transform.position = targetGo.transform.position
                local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
                urpBase:CopyCamera()
            end
        else
            KCookie.Set("UIActionSecondMapDialogEntry", 0)
        end

        if checkNumber(self._regionVo.type) == Constants.RegionSecondMapPointType.Sp then
            local targetGo = self._mapGo.transform:Find("CameraEndPos_" .. self._regionId .. "_1")
            local tPos = targetGo.transform.position

            self._mapCam.transform.position = targetGo.transform.position
            local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
            urpBase:CopyCamera()
        end
    end))
    return coWait
end

function UIActionPointMapDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        Events.RemoveListener("CONSUME_EQUIP_ACTIVITY_NUM", self.handler)
        self.handler = nil
        if not self._isFind then
            RegionQuestMgr:GetInstance():ClearCurMapGo()
        end

        -- if self._co ~= nil then
        --     cs_coroutine.stop(self._co)
        --     self._co = nil
        -- end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

--- 扫荡按钮
function UIActionPointMapDialog:FillSweepBtnGroup()
    local curLevelType = GoodsUtils.GetIdType(self._curSelectQuestId, Constants.IDArea.Quests)
    local canSweep = curLevelType == Constants.IDType.QuestDaily or curLevelType == Constants.IDType.QuestRegion
    KTool.SetActive(self.RT_SweepBtn.gameObject, canSweep)
    if canSweep then
        local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectQuestId)
        local FontBtn = self.RT_SweepBtn:GetComponent(typeof(CS.Game.Native.Common.FontStyleButton))
        if not isNull(FontBtn) then
            FontBtn:ResetFontStyle(isPass and "B25" or "B18")
        end
        SetButtonAction(self.RT_SweepBtn.gameObject, function()
            if isPass then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UISweepPrepareDialog, parameters = { questId = self._curSelectQuestId } })
            else
                GameUtils.Toast(localize("首次通关后解锁扫荡"))
            end
        end)
    end
end

--刷新资源条
function UIActionPointMapDialog:RefreshTopBar()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectQuestId)
    if vo then
        local t = {}
        local id = checkNumber(vo.costItem)
        if id > 0 then
            table.insert(t, id)
        end

        local curLevelType = GoodsUtils.GetIdType(self._curSelectQuestId, Constants.IDArea.Quests)
        if curLevelType == Constants.IDType.QuestDaily then
            table.insert(t, Constants.GoodsId.SweepCoin)
        elseif curLevelType == Constants.IDType.QuestRegion then
            table.insert(t, Constants.GoodsId.SweepCoin)
        end
        CfUtils.RefreshTopGoods(t)
    end
end

--- 刷新扫荡以后会发生变化的数据
function UIActionPointMapDialog:RefreshSweepData()
    self:FillSpInfo()
    self:FillBossInfo()
end

return UIActionPointMapDialog
